import 'package:flutter/material.dart';import 'package:go_router/go_router.dart';import 'package:sehatak/app_router.dart';import 'package:sehatak/core/models/pregnancy/pregnancy_models.dart';import 'package:sehatak/core/services/pregnancy_service.dart';class PregnancyDoctorsScreen extends StatelessWidget{const PregnancyDoctorsScreen({super.key});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('أطباء النساء والتوليد')),body:StreamBuilder<List<PregnancyDoctor>>(stream:PregnancyService().streamDoctors(limit:20),builder:(c,s){if(s.hasError)return Center(child:Text('تعذر تحميل الأطباء'));if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView.builder(padding:const EdgeInsets.all(16),itemCount:s.data!.length,itemBuilder:(c,i){final d=s.data![i];return Card(child:ListTile(onTap:()=>c.push(AppRouter.pregnancyDoctorDetail.replaceFirst(':id',d.id)),leading:CircleAvatar(backgroundImage:d.photoUrl.isNotEmpty?NetworkImage(d.photoUrl):null,child:d.photoUrl.isEmpty?const Icon(Icons.person):null),title:Text(d.name),subtitle:Text('${d.specialty} • ${d.experienceYears} سنة خبرة'),trailing:Text('★${d.rating.toStringAsFixed(1)}'));});}));} }
